from pathlib import Path
import datetime, hashlib, json, re, subprocess
root=Path('/Users/wkoch/Projetos/xrai')
def git(*args): return subprocess.check_output(['git',*args],cwd=root,text=True).strip()
files=['IMPLEMENTADOR.md','README.md','docs/PLANO-DE-IMPLEMENTACAO.md','docs/PLANO-DE-VALIDACAO.md','docs/RFC-0001-ARQUITETURA.md','docs/STATUS-IMPLEMENTACAO.md','docs/decisoes/EXECUCAO-E-CAPTURA.md','docs/decisoes/BIBLIOTECAS-PROPRIAS.md','docs/relatorios/REVISAO-L2.md']
output=root/'docs/relatorios/logs/revisao-L2/documentacao.json'
output.parent.mkdir(parents=True,exist_ok=True)
output.write_text('{}\n')
errors=[]; links=0
for name in files:
 p=root/name
 for target in re.findall(r'\]\(([^)]+)\)',p.read_text()):
  if '://' in target or target.startswith('#'): continue
  target=target.split('#')[0]
  if not target: continue
  links+=1
  if not (p.parent/target).exists(): errors.append(f'broken link {name}: {target}')
plan=(root/'docs/PLANO-DE-IMPLEMENTACAO.md').read_text()
state=(root/'docs/STATUS-IMPLEMENTACAO.md').read_text()
sections=re.split(r'^### (M[01]-\d+(?:\.R\d+)?) — ',plan,flags=re.M)
cards={sections[i]:sections[i+1] for i in range(1,len(sections),2)}
assert len(cards)==41,len(cards)
state_ids=re.findall(r'^\| (M[01]-\d+(?:\.R\d+)?) \|',state,re.M)
if set(cards)!=set(state_ids) or len(state_ids)!=len(cards): errors.append('plan/state IDs differ')
deps={}
for card,body in cards.items():
 m=re.search(r'\*\*Depende de:\*\*(.*?)(?=\*\*|\n)',body)
 if not m: errors.append(f'no dependencies {card}'); continue
 deps[card]=re.findall(r'M[01]-\d+(?:\.R\d+)?',m.group(1))
 for dep in deps[card]:
  if dep not in cards: errors.append(f'unknown dependency {card}->{dep}')
seen=set(); active=set()
def visit(card):
 if card in active: errors.append('cycle '+card);return
 if card in seen:return
 active.add(card)
 for dep in deps.get(card,[]):visit(dep)
 active.remove(card);seen.add(card)
for card in cards:visit(card)
review=(root/'docs/relatorios/REVISAO-L2.md').read_text()
l3=re.findall(r'^### (L3-\d+) — ',review,re.M)
if l3!=[f'L3-{i:02d}' for i in range(1,9)]:errors.append('L3 IDs incomplete/duplicated')
for ident in ['M0-04.R1','M0-08.R1']:
 if not re.search(r'^\| '+re.escape(ident)+r' \|[^\n]*\| não iniciada \|',state,re.M):errors.append('incorrect new state '+ident)
for gate in ['G0','G1','G2']:
 if f'| {gate} | não avaliado |' not in state:errors.append('gate changed '+gate)
changed=git('diff','--name-only').splitlines()+git('ls-files','--others','--exclude-standard').splitlines()
allowed=set(files+[str(output.relative_to(root))])
if set(changed)!=allowed:errors.append('unexpected/missing changed files '+str(set(changed)^allowed))
check=subprocess.run(['git','diff','--check'],cwd=root,capture_output=True,text=True)
if check.returncode:errors.append(check.stdout+check.stderr)
inputs=['Cargo.toml','crates/xrai-eval/Cargo.toml','crates/xrai-eval/harness/runner.py','crates/xrai-eval/src/filesystem_spike.rs','crates/xrai-eval/src/parsing_spike.rs','docs/relatorios/L2.md','docs/relatorios/logs/L2/ci-native-validation.json','eval/qualification/admission-status.json']
def hashes(names):return {n:hashlib.sha256((root/n).read_bytes()).hexdigest() for n in names}
record={'kind':'architecture_documentation_verification','at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'user_date':'2026-10-12','base_commit':git('rev-parse','HEAD'),'branch':git('branch','--show-current'),'command':'python3 /tmp/xrai-verify-architecture.py','verifier_source':Path(__file__).read_text(),'result':'passed' if not errors else 'failed','exit_code':bool(errors)*1,'checks':{'local_links':links,'cards':len(cards),'main_cards':sum('.R' not in c for c in cards),'complementary_cards':sum('.R' in c for c in cards),'plan_status_ids_match':set(cards)==set(state_ids),'dependencies_acyclic':not any(e.startswith('cycle') for e in errors),'l3_cards':l3,'gates_unchanged':True,'only_documentation_modified':set(changed)==allowed,'git_diff_check_exit':check.returncode},'dependencies':deps,'errors':errors,'artifact_sha256':hashes(files),'evidence_inputs_sha256':hashes(inputs),'scope_limitations':['No Rust/product tests or experiments run: documentation only.','Prior native CI attributed to implementer receipts, not rerun or newly queried.','Codebase-memory first generation 2026-10-12T01:50:21Z missed L2 files: source fallback. Later documentary coverage 2026-10-12T09:29:51Z matched 15 consulted paths.','No paid calls or implementation delegated.','Publication not asserted by this pre-commit receipt.']}
output.write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'result':record['result'],'checks':record['checks'],'errors':errors},ensure_ascii=False,indent=2))
raise SystemExit(bool(errors))
